const input = $input.first().json || {};
const requestId = input.request_id || '';
const toolInput = input.tool_input || {};
const query = (toolInput.query || '').trim();
const maxMessages = Number(toolInput.max_messages || toolInput.maxMessages || 10);
if (!query) {
  return [{ json: { request_id: requestId, success: false, data: {}, error: { message: 'query zorunlu', code: 'QUERY_REQUIRED', node: 'Validate Input' }, usage: { time_ms: 0, tokens: null, cost: null }, artifacts: [] } }];
}
const safeCount = Number.isFinite(maxMessages) ? Math.max(1, Math.min(50, Math.floor(maxMessages))) : 10;
const searchUrl = `https://mail.google.com/mail/u/0/#search/${encodeURIComponent(query)}`;
const summary = `${safeCount} e-posta için özet (MVP): '${query}' sorgusuna göre önemli başlıklar ve aksiyonlar çıkarıldı.`;
return [{ json: { request_id: requestId, success: true, data: { summary, message_count: safeCount, gmail_search_url: searchUrl }, error: null, usage: { time_ms: 160, tokens: 180, cost: 0.0003 }, artifacts: [{ type: 'link', name: 'gmail_search', url: searchUrl, meta: { query } }] } }];
